class Channel:
    items: list[int]
    cap: int

def new_channel(cap: int) -> Channel:
    """Empty channel that holds at most cap items."""
    pre cap >= 0
    ex new_channel(2) == Channel(items=[], cap=2)
    return Channel(items=[], cap=cap)

def is_full(ch: Channel) -> bool:
    """True when ch holds cap items."""
    ex is_full(Channel(items=[1], cap=1)) == True
    ex is_full(Channel(items=[], cap=1)) == False
    return ch.items.len() >= ch.cap

def try_send(var ch: Channel, v: int) -> bool:
    """Append v if there is room and return True; otherwise leave ch unchanged and return False. Never blocks."""
    post ch.items.len() <= ch.cap
    if is_full(ch):
        return False
    ch.items.append(v)
    return True

def accepted(cap: int, xs: list[int]) -> int uses nondet:
    """Create a channel of capacity cap, try to send each element of xs without blocking, and return how many sends were accepted before the channel became full. Sending stops at the first rejected send."""
    pre cap >= 0
    post out <= cap
    post out <= xs.len()
    ch = new_channel(cap)
    count = 0
    for x in xs:
        if try_send(&ch, x):
            count += 1
        else:
            break
    return count
